import 'symptom_insight_analyzer.dart';

/// Turns [SymptomInsight]s into user-facing sentences in Arabic or English.
///
/// We keep the wording templated (rather than generated by an LLM) because:
///   - The data here is always small and structured (symptom + phase + %).
///   - Deterministic output makes A/B testing easier.
///   - No tokens, no latency, no failure mode — even works fully offline.
///
/// Add new templates below and reference them from [InsightMessageBuilder].
class InsightMessageBuilder {
  const InsightMessageBuilder();

  /// "صداعك يظهر في 80% من دوراتك، غالباً في المرحلة الأصفر."
  String buildHeadline(SymptomInsight insight, {required bool isArabic}) {
    final pct = insight.confidence;
    final phase = insight.phaseLabel(isArabic ? 'ar' : 'en');
    if (isArabic) {
      return '${insight.symptomName} غالباً يظهر في $phase ($pct%)';
    }
    return '${insight.symptomName} most often appears in your $phase ($pct%)';
  }

  /// "Based on 5 logged cycles. Cramps show up before your period in 4 of them."
  String buildSubtitle(SymptomInsight insight, {required bool isArabic}) {
    final samples = insight.samples;
    if (isArabic) {
      return 'استناداً إلى $samples دورات مسجلة';
    }
    return 'Based on $samples logged cycles';
  }

  /// Optional actionable tip. Kept deliberately generic so we never make
  /// medical claims — see medical safety in `ai_prompt_style.dart`.
  String? buildTip(SymptomInsight insight, {required bool isArabic}) {
    switch (insight.dominantPhase) {
      case 'menstruation':
        return isArabic
            ? 'سجّلي الأعراض يومياً في فترة الدورة لرؤية النمط بشكل أوضح.'
            : 'Log symptoms daily during your period for a clearer pattern.';
      case 'luteal':
        return isArabic
            ? 'في المرحلة الأصفر، خذي راحة إضافية وركّزي على النوم.'
            : 'In your luteal phase, prioritise rest and good sleep.';
      case 'ovulation':
        return isArabic
            ? 'في فترة التبويض، الأعراض مثل آلام البطن الخفيفة شائعة.'
            : 'Mild abdominal aches around ovulation are common.';
      case 'follicular':
        return isArabic
            ? 'الطاقة عادة ترتفع في هذه المرحلة — استثمريها في نشاطات مهمة.'
            : 'Energy usually rises here — great time for important tasks.';
      default:
        return null;
    }
  }
}